from typing import List
from collections import defaultdict

class Solution:
    def maxSubarraySum(self, nums: List[int]) -> int:
        total = nums[0]
        best = nums[0]
        for x in nums[1:]:
            total = max(x, total + x)
            best = max(best, total)

        dp = {}
        count = defaultdict(int)

        for x in nums:
            count[x] += 1
            next_dp = {}

            for v, cur in dp.items():
                if x == v:
                    val = cur
                else:
                    val = cur + x
                if val > next_dp.get(v, float("-inf")):
                    next_dp[v] = val

            if x < 0:
                val = dp.get(x, 0)
                if val > next_dp.get(x, float("-inf")):
                    next_dp[x] = val

            dp = {}
            for v, val in next_dp.items():
                if val > 0 or count[v] < len(nums):
                    dp[v] = val
                    if count[v] < len(nums):
                        best = max(best, val)

        return best
